77	/**
78	 * Pusti dal jen prihlaseneho uzivatele s roli $role (admin muze vsechno),
79	 * jinak vyhodi AccessDenied (-> 403). Bez $role staci byt prihlaseny.
80	 *
81	 * Firewall pred /admin pousti jen ROLE_STAFF, roli stare administrace
82	 * (admin, obchod, sklad, ucetni) prebira LegacyFrontController z roli
83	 * Symfony uzivatele (ROLE_ADMIN, ROLE_OBCHOD, ...).
84	 */
85	function auth_require($role = null)
86	{
87	    if (auth_user() === null) {
88	        throw new AccessDenied('Nepřihlášený uživatel');
89	    }
90	    if ($role !== null && !auth_has_role($role)) {
91	        throw new AccessDenied('Nemáte oprávnění');
92	    }
93	
94	    return true;
95	}
